package water

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Status 表示样品所处的判定状态。
type Status string

const (
	// StatusPending 样品已录入，尚未确认判定结果。
	StatusPending Status = "pending"
	// StatusConfirmed 样品已确认，判定结果已保存。
	StatusConfirmed Status = "confirmed"
	// StatusVoided 样品已作废，保留记录但不能再确认。
	StatusVoided Status = "voided"
)

var (
	ErrClosed             = errors.New("water: 数据存放已关闭")
	ErrEmptyField         = errors.New("water: 编号、名称或项目去掉首尾空白后不能为空")
	ErrDuplicatePoint     = errors.New("water: 采样点编号已登记")
	ErrUnknownPoint       = errors.New("water: 采样点未登记")
	ErrInvalidValue       = errors.New("water: 数值只接受有限数")
	ErrInvalidTime        = errors.New("water: 采样时间或生效时间缺失")
	ErrDuplicateLimitTime = errors.New("water: 同一采样点同一项目已存在相同生效时间的上限")
	ErrUnknownSample      = errors.New("water: 样品编号不存在")
	ErrSampleConflict     = errors.New("water: 同一编号提交的样品内容不一致")
	ErrDuplicateItem      = errors.New("water: 同一份样品的测量项目重复")
	ErrNoMeasurements     = errors.New("water: 样品至少需要一个项目的测量值")
	ErrMissingLimit       = errors.New("water: 存在找不到适用上限的测量项目")
	ErrVoided             = errors.New("water: 样品已作废，不能再确认")
	ErrVoidReasonConflict = errors.New("water: 作废原因与已有记录不一致")
)

// SamplingPoint 是按编号唯一登记的采样点。
type SamplingPoint struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

// Limit 是某采样点某测量项目的一版数值上限。
type Limit struct {
	PointID   string    `json:"pointId"`
	Item      string    `json:"item"`
	Value     float64   `json:"value"`
	Effective time.Time `json:"effective"`
}

// Measurement 是样品中一个项目的测量值。
type Measurement struct {
	Item  string  `json:"item"`
	Value float64 `json:"value"`
}

// ItemResult 是确认后单个项目的判定结果。
type ItemResult struct {
	Item           string    `json:"item"`
	Value          float64   `json:"value"`
	Limit          float64   `json:"limit"`
	LimitEffective time.Time `json:"limitEffective"`
	Exceeded       bool      `json:"exceeded"`
}

// Sample 是一份从录入、确认到作废的样品记录。
type Sample struct {
	ID           string        `json:"id"`
	PointID      string        `json:"pointId"`
	SampledAt    time.Time     `json:"sampledAt"`
	Measurements []Measurement `json:"measurements"`
	Status       Status        `json:"status"`
	Results      []ItemResult  `json:"results,omitempty"`
	Exceeded     bool          `json:"exceeded"`
	VoidReason   string        `json:"voidReason,omitempty"`
}

// diskState 是落盘的完整数据。
type diskState struct {
	Points  map[string]SamplingPoint `json:"points"`
	Limits  map[string][]Limit       `json:"limits"` // 键仅为落盘占位，读取时按每条限值自身的采样点与项目重新分组
	Samples map[string]*Sample       `json:"samples"`
}

// limitGroup 用两个字段各自标识一组限值，避免把包含 U+0000 的文本
// 用单字符拼接成键时不同组合撞成同一组。
type limitGroup struct {
	pointID string
	item    string
}

// Store 是绑定到某个本地目录的取样判定数据存放。
// 不同目录的数据互不混用；关闭后重新打开仍能查看原有记录。
type Store struct {
	mu      sync.Mutex
	dir     string
	file    string
	closed  bool
	points  map[string]SamplingPoint
	limits  map[limitGroup][]Limit // 按生效时间升序
	samples map[string]*Sample
}

// Open 打开（必要时创建）dir 下的本地数据存放。
func Open(dir string) (*Store, error) {
	if strings.TrimSpace(dir) == "" {
		return nil, fmt.Errorf("%w: 数据目录", ErrEmptyField)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	s := &Store{
		dir:     dir,
		file:    filepath.Join(dir, "water-data.json"),
		points:  map[string]SamplingPoint{},
		limits:  map[limitGroup][]Limit{},
		samples: map[string]*Sample{},
	}
	data, err := os.ReadFile(s.file)
	if errors.Is(err, fs.ErrNotExist) {
		return s, nil
	}
	if err != nil {
		return nil, err
	}
	var st diskState
	if err := json.Unmarshal(data, &st); err != nil {
		return nil, fmt.Errorf("water: 读取数据文件失败: %w", err)
	}
	if st.Points != nil {
		s.points = st.Points
	}
	if st.Limits != nil {
		// 不按落盘键分组：键可能是旧版本用单字符拼接生成的，包含 U+0000 的
		// 不同（采样点，项目）组合会共用同一个键。以每条限值自身的两个字段为准，
		// 让曾经被错误合并的组在重新打开时也能各自归位。
		for _, versions := range st.Limits {
			for _, lim := range versions {
				g := limitGroup{pointID: lim.PointID, item: lim.Item}
				s.limits[g] = append(s.limits[g], lim)
			}
		}
		for g, versions := range s.limits {
			sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
			s.limits[g] = versions
		}
	}
	if st.Samples != nil {
		s.samples = st.Samples
	}
	return s, nil
}

// Close 关闭数据存放。已保存的记录已落盘，重新 Open 同一目录即可查看。
func (s *Store) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return nil
	}
	s.closed = true
	return nil
}

func clean(s string) string { return strings.TrimSpace(s) }

// diskLimitKey 生成仅用于落盘 JSON 的分组键。带上两个字段的长度前缀，
// 任何包含 U+0000 的文本组合都不会撞键；读取时并不依赖该键分组。
func diskLimitKey(pointID, item string) string {
	return strconv.Itoa(len(pointID)) + ":" + pointID + strconv.Itoa(len(item)) + ":" + item
}

func finite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }

func (s *Store) checkOpenLocked() error {
	if s.closed {
		return ErrClosed
	}
	return nil
}

// persistLocked 把全部数据原子写回数据文件。只在成功变更后调用，
// 被拒绝的操作不会走到这里，因此不会留下新增或变更记录。
func (s *Store) persistLocked() error {
	diskLimits := make(map[string][]Limit, len(s.limits))
	for g, versions := range s.limits {
		diskLimits[diskLimitKey(g.pointID, g.item)] = versions
	}
	data, err := json.MarshalIndent(diskState{
		Points:  s.points,
		Limits:  diskLimits,
		Samples: s.samples,
	}, "", "  ")
	if err != nil {
		return err
	}
	tmp := s.file + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, s.file)
}

// RegisterPoint 登记采样点。编号、名称去掉首尾空白后不能为空，
// 保存和比较均使用处理后的文本；重复编号拒绝。
func (s *Store) RegisterPoint(id, name string) (SamplingPoint, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpenLocked(); err != nil {
		return SamplingPoint{}, err
	}
	id, name = clean(id), clean(name)
	if id == "" || name == "" {
		return SamplingPoint{}, ErrEmptyField
	}
	if _, ok := s.points[id]; ok {
		return SamplingPoint{}, fmt.Errorf("%w: %s", ErrDuplicatePoint, id)
	}
	p := SamplingPoint{ID: id, Name: name}
	s.points[id] = p
	if err := s.persistLocked(); err != nil {
		delete(s.points, id)
		return SamplingPoint{}, err
	}
	return p, nil
}

// SetLimit 为已登记采样点的某个测量项目登记一版数值上限及生效时间。
// 允许乱序补录；生效时间相同（不同时区表示的同一时刻也算相同）的第二条拒绝。
func (s *Store) SetLimit(pointID, item string, value float64, effective time.Time) (Limit, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpenLocked(); err != nil {
		return Limit{}, err
	}
	pointID, item = clean(pointID), clean(item)
	if pointID == "" || item == "" {
		return Limit{}, ErrEmptyField
	}
	if _, ok := s.points[pointID]; !ok {
		return Limit{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
	}
	if !finite(value) {
		return Limit{}, ErrInvalidValue
	}
	if effective.IsZero() {
		return Limit{}, ErrInvalidTime
	}
	lim := Limit{PointID: pointID, Item: item, Value: value, Effective: effective.UTC()}
	g := limitGroup{pointID: pointID, item: item}
	versions := s.limits[g]
	for _, v := range versions {
		if v.Effective.Equal(lim.Effective) {
			return Limit{}, fmt.Errorf("%w: %s/%s @ %s", ErrDuplicateLimitTime, pointID, item, lim.Effective)
		}
	}
	old := s.limits[g]
	// 复制到新切片再插入排序：append/sort 会原地改动共享底层数组，
	// 一旦保存失败需要回滚，old 必须仍是调用前的完整状态。
	versions = make([]Limit, len(old)+1)
	copy(versions, old)
	versions[len(old)] = lim
	sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
	s.limits[g] = versions
	if err := s.persistLocked(); err != nil {
		s.limits[g] = old
		return Limit{}, err
	}
	return lim, nil
}

// SubmitSample 录入一份样品，初始为待判定状态。
// 再次提交同一编号且内容相同（项目排列顺序不同不算变化）返回原样品；
// 任一内容不同则拒绝整个提交，已确认或已作废的样品同样遵守。
func (s *Store) SubmitSample(id, pointID string, sampledAt time.Time, measurements ...Measurement) (Sample, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpenLocked(); err != nil {
		return Sample{}, err
	}
	id, pointID = clean(id), clean(pointID)
	if id == "" || pointID == "" {
		return Sample{}, ErrEmptyField
	}
	if sampledAt.IsZero() {
		return Sample{}, ErrInvalidTime
	}
	if len(measurements) == 0 {
		return Sample{}, ErrNoMeasurements
	}
	ms := make([]Measurement, len(measurements))
	seen := make(map[string]float64, len(measurements))
	for i, m := range measurements {
		item := clean(m.Item)
		if item == "" {
			return Sample{}, ErrEmptyField
		}
		if !finite(m.Value) {
			return Sample{}, ErrInvalidValue
		}
		if _, dup := seen[item]; dup {
			return Sample{}, fmt.Errorf("%w: %s", ErrDuplicateItem, item)
		}
		seen[item] = m.Value
		ms[i] = Measurement{Item: item, Value: m.Value}
	}
	sampledAt = sampledAt.UTC()

	if existing, ok := s.samples[id]; ok {
		if sameSampleContent(existing, pointID, sampledAt, seen) {
			return copySample(existing), nil
		}
		return Sample{}, fmt.Errorf("%w: %s", ErrSampleConflict, id)
	}
	if _, ok := s.points[pointID]; !ok {
		return Sample{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
	}
	smp := &Sample{
		ID:           id,
		PointID:      pointID,
		SampledAt:    sampledAt,
		Measurements: ms,
		Status:       StatusPending,
	}
	s.samples[id] = smp
	if err := s.persistLocked(); err != nil {
		delete(s.samples, id)
		return Sample{}, err
	}
	return copySample(smp), nil
}

func sameSampleContent(s *Sample, pointID string, sampledAt time.Time, ms map[string]float64) bool {
	if s.PointID != pointID || !s.SampledAt.Equal(sampledAt) || len(s.Measurements) != len(ms) {
		return false
	}
	for _, m := range s.Measurements {
		v, ok := ms[m.Item]
		if !ok || v != m.Value {
			return false
		}
	}
	return true
}

// Confirm 确认一份待判定样品：每个项目取生效时间不晚于采样时间的最近一版上限，
// 测量值大于上限才超标，任一项目超标则整份样品超标。
// 只要有项目找不到适用上限，本次确认拒绝，样品保持待判定。
// 重复确认直接返回已保存结果；之后新增或补录限值不改变已确认结果。
func (s *Store) Confirm(id string) (Sample, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpenLocked(); err != nil {
		return Sample{}, err
	}
	id = clean(id)
	if id == "" {
		return Sample{}, ErrEmptyField
	}
	smp, ok := s.samples[id]
	if !ok {
		return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
	}
	switch smp.Status {
	case StatusVoided:
		return Sample{}, fmt.Errorf("%w: %s", ErrVoided, id)
	case StatusConfirmed:
		return copySample(smp), nil
	}

	results := make([]ItemResult, 0, len(smp.Measurements))
	exceeded := false
	for _, m := range smp.Measurements {
		lim, ok := applicableLimit(s.limits[limitGroup{pointID: smp.PointID, item: m.Item}], smp.SampledAt)
		if !ok {
			return Sample{}, fmt.Errorf("%w: 样品 %s 的项目 %s", ErrMissingLimit, id, m.Item)
		}
		ex := m.Value > lim.Value
		if ex {
			exceeded = true
		}
		results = append(results, ItemResult{
			Item:           m.Item,
			Value:          m.Value,
			Limit:          lim.Value,
			LimitEffective: lim.Effective,
			Exceeded:       ex,
		})
	}
	smp.Results = results
	smp.Exceeded = exceeded
	smp.Status = StatusConfirmed
	if err := s.persistLocked(); err != nil {
		smp.Results = nil
		smp.Exceeded = false
		smp.Status = StatusPending
		return Sample{}, err
	}
	return copySample(smp), nil
}

// applicableLimit 在按生效时间升序的版本里取不晚于 at 的最近一版；
// 采样时间恰好等于生效时间时使用该版新值。
func applicableLimit(versions []Limit, at time.Time) (Limit, bool) {
	best := -1
	for i, v := range versions {
		if v.Effective.After(at) {
			break
		}
		best = i
	}
	if best < 0 {
		return Limit{}, false
	}
	return versions[best], true
}

// Void 作废样品。原因去掉首尾空白后不能为空；待判定和已确认的样品都能作废。
// 作废后保留测量、原因和已有结果；重复提交处理后相同的原因返回原记录，不同则拒绝。
func (s *Store) Void(id, reason string) (Sample, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpenLocked(); err != nil {
		return Sample{}, err
	}
	id, reason = clean(id), clean(reason)
	if id == "" || reason == "" {
		return Sample{}, ErrEmptyField
	}
	smp, ok := s.samples[id]
	if !ok {
		return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
	}
	if smp.Status == StatusVoided {
		if smp.VoidReason == reason {
			return copySample(smp), nil
		}
		return Sample{}, fmt.Errorf("%w: %s", ErrVoidReasonConflict, id)
	}
	oldStatus := smp.Status
	smp.Status = StatusVoided
	smp.VoidReason = reason
	if err := s.persistLocked(); err != nil {
		smp.Status = oldStatus
		smp.VoidReason = ""
		return Sample{}, err
	}
	return copySample(smp), nil
}

// ListByPoint 按采样点查看样品，按采样时间从晚到早排列，同一时刻按样品编号升序。
func (s *Store) ListByPoint(pointID string) ([]Sample, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpenLocked(); err != nil {
		return nil, err
	}
	return s.pointSamplesLocked(clean(pointID), func(*Sample) bool { return true }), nil
}

// LatestResult 返回该采样点最近有效的已确认样品（跳过待判定与已作废）。
// 没有已确认且未作废的样品时 ok 为 false。
func (s *Store) LatestResult(pointID string) (smp Sample, ok bool, err error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpenLocked(); err != nil {
		return Sample{}, false, err
	}
	list := s.pointSamplesLocked(clean(pointID), func(smp *Sample) bool {
		return smp.Status == StatusConfirmed
	})
	if len(list) == 0 {
		return Sample{}, false, nil
	}
	return list[0], true, nil
}

// pointSamplesLocked 收集某采样点符合 keep 的样品，逐份复制后按统一规则排列，
// 供 ListByPoint 与 LatestResult 共用，保证两种查询对同一批样品的先后判断一致。
// 调用方须已持有锁；pointID 须已做首尾空白处理。
func (s *Store) pointSamplesLocked(pointID string, keep func(*Sample) bool) []Sample {
	var list []Sample
	for _, smp := range s.samples {
		if smp.PointID == pointID && keep(smp) {
			list = append(list, copySample(smp))
		}
	}
	sortSamples(list)
	return list
}

func sortSamples(list []Sample) {
	sort.Slice(list, func(i, j int) bool {
		a, b := list[i], list[j]
		if !a.SampledAt.Equal(b.SampledAt) {
			return a.SampledAt.After(b.SampledAt)
		}
		return a.ID < b.ID
	})
}

func copySample(s *Sample) Sample {
	c := *s
	c.Measurements = append([]Measurement(nil), s.Measurements...)
	c.Results = append([]ItemResult(nil), s.Results...)
	return c
}

package water

import (
	"errors"
	"reflect"
	"testing"
	"time"
)

// 本文件的测试只针对一件事：已确认样品被同编号、同内容重复录入（重报）时，
// 返回的必须是首次录入并已保存判定依据的那条记录——确认之后补录、且已适用
// 于采样时刻的新版限值不能触发重新判定，状态不能退回待判定，首次录入的
// 项目排列不能被后一次提交的排列替换，另一项目已保存的依据也不能丢。
// 内容冲突与同份提交内项目重复沿用现有的 ErrSampleConflict、ErrDuplicateItem
// 整体拒绝并返回空样品；拒绝不留痕，之后提交合法原内容仍返回原已确认记录。
// 录入、查询入口与错误含义均保持现状。

// checkConfirmedResubmit 锁定重报返回的就是首次确认时保存的记录。
// checkTwoItemSaved 已覆盖：编号 S1、采样点 P1、已确认状态、采样时间、
// pH 9 > 8@09-01 超标、COD 30 == 30@09-01 达标、整份超标；这里再锁定
// Measurements 与 Results 的项目排列必须是首次录入的 pH、COD 顺序。
func checkConfirmedResubmit(t *testing.T, smp Sample, label string) {
	t.Helper()
	checkTwoItemSaved(t, smp, label)
	want := []string{"pH", "COD"}
	gotM := make([]string, len(smp.Measurements))
	for i, m := range smp.Measurements {
		gotM[i] = m.Item
	}
	if !reflect.DeepEqual(gotM, want) {
		t.Fatalf("%s: 测量排列应保持首次录入的 pH、COD，不能用后一次提交的排列替换: %v",
			label, gotM)
	}
	gotR := make([]string, len(smp.Results))
	for i, r := range smp.Results {
		gotR[i] = r.Item
	}
	if !reflect.DeepEqual(gotR, want) {
		t.Fatalf("%s: 逐项结果排列应保持首次录入的 pH、COD: %v", label, gotR)
	}
}

// checkEmptySample 锁定被拒绝的提交返回空样品：连编号和状态都是零值，
// 调用方不能忽略 err 后把它当成新录入或已确认的记录使用。
func checkEmptySample(t *testing.T, smp Sample, label string) {
	t.Helper()
	if smp.ID != "" || smp.PointID != "" || smp.Status != "" ||
		len(smp.Measurements) != 0 || len(smp.Results) != 0 || smp.Exceeded ||
		smp.VoidReason != "" || !smp.SampledAt.IsZero() {
		t.Fatalf("%s: 被拒绝时应返回空样品，实际为: %+v", label, smp)
	}
}

// 已确认样品 S1（pH 9 > 8@09-01 超标，COD 30 == 30@09-01 达标，整份超标）
// 确认后补录一版 09-09 生效的 pH 上限 10：它对 09-10 的采样时刻已经适用，
// 若重新判定 pH 9 < 10 会变成达标、整份也变达标。随后重复录入原来的两个
// 测量值，返回的仍必须是原已确认样品：pH 所用上限仍为 8、生效时间仍为
// 09-01，各项与整份结论保持原样，不能变回待判定，也不能丢掉 COD 的依据。
//
// 交换项目顺序、编号/采样点/项目名带首尾空白、采样时间换另一时区表示同一
// 瞬间都不构成内容变化；每次成功返回都与首次确认返回逐字段一致，并保持
// 首次录入的项目排列。按采样点查看 S1 只出现一次；该点没有其他样品时，
// 最近有效结果仍是这份已确认的超标样品，测量值、所用限值和生效时间与
// 重报返回一致。重报是幂等返回，不写盘；关闭后重新打开，保存的依据不变，
// 在新进程里重报原内容仍返回同一条记录。
func TestResubmitConfirmedKeepsSavedBasis(t *testing.T) {
	s, dir := open(t)
	mustPoint(t, s, "P1", "取水口")
	mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
	mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
	first := mustSample(t, s, "S1", "P1", at(10, 0),
		Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
	if first.Status != StatusPending || len(first.Results) != 0 {
		t.Fatalf("首次录入应为无判定依据的待判定样品: %+v", first)
	}
	confirmed, err := s.Confirm("S1")
	if err != nil {
		t.Fatalf("Confirm S1: %v", err)
	}
	checkConfirmedResubmit(t, confirmed, "首次确认")

	// 确认后补录新版 pH 上限：10@09-09 对 09-10 的采样已经生效，
	// 但它只能被此后“新”的判定采用，不能回头重算这份已确认样品。
	mustLimit(t, s, "P1", "pH", 10.0, at(9, 0))

	cst := time.FixedZone("CST", 8*3600) // 2026-09-10 08:00 +08:00 == 00:00 UTC
	cases := []struct {
		name      string
		id        string
		point     string
		sampledAt time.Time
		ms        []Measurement
	}{
		{
			name:      "交换两个项目的提交顺序",
			id:        "S1",
			point:     "P1",
			sampledAt: at(10, 0),
			ms: []Measurement{
				{Item: "COD", Value: 30},
				{Item: "pH", Value: 9},
			},
		},
		{
			name:      "编号带首尾空白",
			id:        "  S1  ",
			point:     "P1",
			sampledAt: at(10, 0),
			ms: []Measurement{
				{Item: "pH", Value: 9},
				{Item: "COD", Value: 30},
			},
		},
		{
			name:      "采样点编号与项目名称带首尾空白",
			id:        "S1",
			point:     "  P1 ",
			sampledAt: at(10, 0),
			ms: []Measurement{
				{Item: "  pH ", Value: 9},
				{Item: " COD ", Value: 30},
			},
		},
		{
			name:      "采样时间换成另一时区对同一瞬间的表示",
			id:        "S1",
			point:     "P1",
			sampledAt: time.Date(2026, 9, 10, 8, 0, 0, 0, cst),
			ms: []Measurement{
				{Item: "pH", Value: 9},
				{Item: "COD", Value: 30},
			},
		},
		{
			name:      "顺序空白时区差别叠加",
			id:        " S1 ",
			point:     " P1  ",
			sampledAt: time.Date(2026, 9, 10, 8, 0, 0, 0, cst),
			ms: []Measurement{
				{Item: " COD ", Value: 30},
				{Item: "  pH  ", Value: 9},
			},
		},
	}
	for _, c := range cases {
		got, err := s.SubmitSample(c.id, c.point, c.sampledAt, c.ms...)
		if err != nil {
			t.Fatalf("重报原内容（%s）不应被拒绝: %v", c.name, err)
		}
		checkConfirmedResubmit(t, got, "重报（"+c.name+"）")
		// 不能当成新样品，也不能用后一次内容重算：与首次确认返回逐字段一致。
		if !reflect.DeepEqual(got, confirmed) {
			t.Fatalf("重报（%s）应原样返回首次确认的记录:\n got %+v\nwant %+v",
				c.name, got, confirmed)
		}
	}

	// 按采样点查看：重报不产生新样品，S1 只出现一次且内容与重报返回一致。
	list, err := s.ListByPoint("P1")
	if err != nil || len(list) != 1 {
		t.Fatalf("ListByPoint 应只有 S1 一份: %+v err=%v", list, err)
	}
	checkConfirmedResubmit(t, list[0], "重报后按点查询")
	if !reflect.DeepEqual(list[0], confirmed) {
		t.Fatalf("按点查询与首次确认记录不一致:\n got %+v\nwant %+v", list[0], confirmed)
	}

	// 该点没有其他样品时，最近有效结果仍是这份已确认的超标样品，
	// 测量值、所用限值、生效时间与重报返回完全一致。
	latest, ok, err := s.LatestResult("P1")
	if err != nil || !ok {
		t.Fatalf("最近有效结果应仍指向 S1: %+v ok=%v err=%v", latest, ok, err)
	}
	checkConfirmedResubmit(t, latest, "重报后最近有效结果")
	if !reflect.DeepEqual(latest, confirmed) {
		t.Fatalf("最近有效结果与首次确认记录不一致:\n got %+v\nwant %+v", latest, confirmed)
	}

	// 幂等重报不写盘：关闭后重新打开同一目录，已保存的判定依据原样保留。
	if err := s.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	reopened, err := Open(dir)
	if err != nil {
		t.Fatalf("重新 Open: %v", err)
	}
	t.Cleanup(func() { reopened.Close() })

	list2, err := reopened.ListByPoint("P1")
	if err != nil || len(list2) != 1 {
		t.Fatalf("重开后 ListByPoint 应只有 S1 一份: %+v err=%v", list2, err)
	}
	checkConfirmedResubmit(t, list2[0], "重开后按点查询")
	latest2, ok, err := reopened.LatestResult("P1")
	if err != nil || !ok {
		t.Fatalf("重开后最近有效结果应仍指向 S1: %+v ok=%v err=%v", latest2, ok, err)
	}
	checkConfirmedResubmit(t, latest2, "重开后最近有效结果")

	// 新进程里重报原内容（换序、空白、另一时区）仍返回同一条已确认记录，
	// 不会因补录的 10@09-09 重新判定，也不会产生第二份样品。
	again, err := reopened.SubmitSample(" S1 ", " P1 ",
		time.Date(2026, 9, 10, 8, 0, 0, 0, cst),
		Measurement{Item: "COD", Value: 30}, Measurement{Item: " pH ", Value: 9})
	if err != nil {
		t.Fatalf("重开后重报原内容: %v", err)
	}
	checkConfirmedResubmit(t, again, "重开后重报")
	if !reflect.DeepEqual(again, confirmed) {
		t.Fatalf("重开后重报应返回原已确认记录:\n got %+v\nwant %+v", again, confirmed)
	}
	list3, err := reopened.ListByPoint("P1")
	if err != nil || len(list3) != 1 {
		t.Fatalf("重开后重报不应产生新样品: %+v err=%v", list3, err)
	}
}

// 重报已确认样品时，仅把 COD 的测量值改成另一个有限数，属于样品内容冲突，
// 必须以现有的 ErrSampleConflict 整体拒绝并返回空样品；同一份重报里出现两个
// 去掉首尾空白后名称相同的项目（即使值相同），必须以现有的
// ErrDuplicateItem 拒绝，不能把两个同名项目合并后视为内容相同而幂等返回。
// 两种拒绝都不留痕：原记录的状态、测量、逐项依据与整份结论不变，按点查询
// 仍是唯一一份，最近有效结果仍指向它。拒绝之后再次提交合法的原内容
// （可带换序、空白、另一时区的等价差别），仍能返回原来的已确认记录。
func TestResubmitConfirmedRejectionsKeepRecord(t *testing.T) {
	s, _ := open(t)
	mustPoint(t, s, "P1", "取水口")
	mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
	mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
	mustSample(t, s, "S1", "P1", at(10, 0),
		Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
	confirmed, err := s.Confirm("S1")
	if err != nil {
		t.Fatalf("Confirm S1: %v", err)
	}
	// 同样先补录一版已适用的新 pH 上限，确认拒绝路径也不会顺手重算原记录。
	mustLimit(t, s, "P1", "pH", 10.0, at(9, 0))

	// 每次被拒绝后，列表与最近有效结果都必须仍是原已确认记录，且只有一份。
	assertUntouched := func(label string) {
		t.Helper()
		list, err := s.ListByPoint("P1")
		if err != nil || len(list) != 1 {
			t.Fatalf("%s: ListByPoint 应仍只有 S1 一份: %+v err=%v", label, list, err)
		}
		checkConfirmedResubmit(t, list[0], label+"按点查询")
		latest, ok, err := s.LatestResult("P1")
		if err != nil || !ok {
			t.Fatalf("%s: 最近有效结果应仍指向 S1: %+v ok=%v err=%v",
				label, latest, ok, err)
		}
		checkConfirmedResubmit(t, latest, label+"最近有效结果")
		if !reflect.DeepEqual(latest, confirmed) {
			t.Fatalf("%s: 最近有效结果被改动:\n got %+v\nwant %+v",
				label, latest, confirmed)
		}
	}

	// 1) 仅把 COD 改成另一个有限数（30 -> 31）：内容冲突，整体拒绝。
	conflict, err := s.SubmitSample("S1", "P1", at(10, 0),
		Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 31})
	if !errors.Is(err, ErrSampleConflict) {
		t.Fatalf("COD 改值重报应报样品内容冲突, got %v", err)
	}
	checkEmptySample(t, conflict, "COD 改值重报")
	assertUntouched("COD 改值被拒绝后")

	// 2) 同一份重报两个去空白后同名的项目，且值也相同：项目重复。
	//    若错误地先合并同名项，内容恰好与原记录相同——绝不能因此幂等返回。
	dup, err := s.SubmitSample(" S1 ", "P1", at(10, 0),
		Measurement{Item: " pH ", Value: 9},
		Measurement{Item: "pH", Value: 9},
		Measurement{Item: " COD ", Value: 30})
	if !errors.Is(err, ErrDuplicateItem) {
		t.Fatalf("同份重报同名项目应报项目重复, got %v", err)
	}
	checkEmptySample(t, dup, "同份同名项目重报")
	assertUntouched("同份同名项目被拒绝后")

	// 3) 两种拒绝之后，提交合法的原内容（换序、空白、另一时区），
	//    仍返回原来的已确认记录，依据与排列都保持首次保存的样子。
	cst := time.FixedZone("CST", 8*3600)
	again, err := s.SubmitSample("  S1  ", " P1 ",
		time.Date(2026, 9, 10, 8, 0, 0, 0, cst),
		Measurement{Item: "COD", Value: 30}, Measurement{Item: " pH ", Value: 9})
	if err != nil {
		t.Fatalf("拒绝后重报合法原内容不应失败: %v", err)
	}
	checkConfirmedResubmit(t, again, "拒绝后合法重报")
	if !reflect.DeepEqual(again, confirmed) {
		t.Fatalf("拒绝后合法重报应返回原已确认记录:\n got %+v\nwant %+v",
			again, confirmed)
	}
	list, err := s.ListByPoint("P1")
	if err != nil || len(list) != 1 {
		t.Fatalf("合法重报不应产生新样品: %+v err=%v", list, err)
	}
}

